#!/bin/sh
# Creates MinIO buckets for the ledger platform.
# Runs as a one-shot container after minio is healthy.

set -eu

MINIO_URL="http://minio:9000"
ALIAS="local"

: "${MINIO_ROOT_USER:?MINIO_ROOT_USER env var is required}"
: "${MINIO_ROOT_PASSWORD:?MINIO_ROOT_PASSWORD env var is required}"

echo "Configuring MinIO client alias..."
mc alias set "$ALIAS" "$MINIO_URL" "$MINIO_ROOT_USER" "$MINIO_ROOT_PASSWORD"

echo "Creating buckets..."

# Bank settlement files (NACH, SEPA) — generated by payout-svc.
mc mb --ignore-existing "${ALIAS}/settlement-files"

# Reconciliation reports — generated by recon-worker.
mc mb --ignore-existing "${ALIAS}/recon-reports"

# Bank response files — uploaded by ops after settlement run completes.
mc mb --ignore-existing "${ALIAS}/bank-responses"

# No public access — all access goes through signed URLs or service credentials.
mc anonymous set none "${ALIAS}/settlement-files"
mc anonymous set none "${ALIAS}/recon-reports"
mc anonymous set none "${ALIAS}/bank-responses"

echo "Buckets created:"
mc ls "$ALIAS"
